const item = $input.first().json;
const jobId = item.jobId;
if (!jobId) throw new Error('Missing jobId for full text pipeline');
const apiToken = $env.FAIRYTELLER_API_TOKEN;
if (!apiToken) throw new Error('FAIRYTELLER_API_TOKEN is not configured');
const jobUrl = 'https://fairyteller.ru/api/fairyteller/jobs/' + jobId;

function cleanError(error) {
  const body = error?.response?.body || error?.cause?.response?.body;
  const message = typeof body === 'string'
    ? body
    : body?.error?.message || body?.message || error?.message || 'unknown error';
  return String(message).replace(/\s+/g, ' ').trim().slice(0, 500);
}

async function request(options) {
  return await this.helpers.httpRequest({
    ...options,
    headers: {
      Authorization: 'Bearer ' + apiToken,
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    json: true,
    timeout: options.timeout || 30000,
  });
}

let current = null;
try {
  current = await request.call(this, { method: 'GET', url: jobUrl });
} catch (error) {
  console.log('Could not read current job before full text claim: ' + cleanError(error));
}

const currentFullText = current?.artifacts?.fullText || {};
const currentFullTextStatus = String(currentFullText.status || '').toLowerCase();
const currentLeaseUntil = Date.parse(currentFullText.leaseUntil || '');
const startedAtMs = Date.parse(currentFullText.startedAt || '');
const leaseActive = Number.isFinite(currentLeaseUntil)
  ? currentLeaseUntil > Date.now()
  : (Number.isFinite(startedAtMs) && Date.now() - startedAtMs < 15 * 60 * 1000);
const alreadyClaimed = currentFullTextStatus === 'generating' && leaseActive;
if (currentFullTextStatus === 'ready' || alreadyClaimed) {
  console.log('Full text already ' + currentFullTextStatus + ' for ' + jobId + '; skipping duplicate launch');
  return [];
}

const startedAt = new Date().toISOString();
const leaseUntil = new Date(Date.now() + 15 * 60 * 1000).toISOString();
const generationAttempt = Math.max(1, Number(currentFullText.attempt || 0) + 1);
const progress = Math.max(45, Number(current?.progress || item.progress || 35) || 45);
const trigger = item.pipeline?.fullTextFallback ? 'visuals_fallback' : 'text_fanout';

await request.call(this, {
  method: 'PATCH',
  url: jobUrl,
  body: {
    stage: 'text',
    progress,
    message: 'Пишем продолжение истории',
    artifacts: {
      fullText: { status: 'generating', startedAt, leaseUntil, attempt: generationAttempt, trigger },
    },
  },
});

return [{ json: { ...item, fullTextClaim: { status: 'generating', startedAt, trigger } } }];

const item = $input.first().json;
const order = item.order || {};
const text = item.text || {};
const bible = text.bible || {};
const hasApprovedStoryBrief = Boolean(String(order.approvedStoryBrief || '').trim());
const approvedArtifactCanon = hasApprovedStoryBrief ? String(order.approvedArtifactCanon || '').replace(/\s+/g, ' ').trim().slice(0, 700) : '';
const legacyArtifact = hasApprovedStoryBrief ? '' : String(order.artifact || '').replace(/\s+/g, ' ').trim().slice(0, 350);
const effectiveArtifactCanon = approvedArtifactCanon || bible.artifactCanon || legacyArtifact;
const firstChapter = text.chapters?.[0] || {};
const chapterTextBlockTargets = text.chapterTextBlockTargets || { 1: 4, 2: 4, 3: 6, 4: 6, 5: 5 };
const chaptersTarget = Math.max(1, Math.min(8, Number(order.chapters || bible.chapterPlan?.length || 5)));
const laterNumbers = Array.from({ length: Math.max(0, chaptersTarget - 1) }, (_, index) => index + 2);
const chapterPlan = Array.isArray(bible.chapterPlan) ? bible.chapterPlan : [];
const laterPlan = laterNumbers.map((n) => {
  const planned = chapterPlan.find((chapter) => Number(chapter.n) === n) || { n, title: 'Глава ' + n, beat: '' };
  return { ...planned, n, title: planned.title || ('Глава ' + n), beat: planned.beat || planned.summary || '', textBlockTarget: chapterTextBlockTargets[n] || 5 };
});
const activeHeroes = (order.heroes || []).filter((hero) => hero.name || hero.description || hero.relation || hero.hasPhoto);
const heroCount = activeHeroes.length;
const hasChildHero = activeHeroes.some((hero) => hero.ageGroup === 'child');
const childTonePolicy = hasChildHero
  ? 'ОБЯЗАТЕЛЬНЫЙ ПРИОРИТЕТ: среди героев есть ребенок. Вся история должна оставаться светлой, жизнеутверждающей и эмоционально безопасной. Допустимы загадка, волнение и преодолимые препятствия, но запрещены смерть, жестокость, пытки, безысходность, предательство близких, травмирующее преследование, хоррор и глобальная катастрофа. После напряжения давай передышку, поддержку или юмор; финал теплый, завершенный и обнадеживающий. Это правило важнее жанровой атмосферы.'
  : 'Сохраняй человеческое тепло, эмоциональные передышки и завершенный обнадеживающий финал.';
const protagonistMode = heroCount <= 1 ? 'solo' : (heroCount === 2 ? 'duo' : 'ensemble');
function protagonistPolicyFor(mode) {
  if (mode === 'solo') return 'SOLO: продолжай историю как книгу об одном главном герое. Не добавляй второго постоянного героя, напарника, романтического партнера или co-hero. Эпизодические встречные персонажи допустимы, но они не проходят весь сюжет и не получают равную арку.';
  if (mode === 'duo') return 'DUO: держи фокус на двух заданных героях. Не добавляй третьего постоянного спутника.';
  return 'ENSEMBLE: держи фокус только на заданных пользователем героях. Не добавляй новых постоянных участников команды.';
}
function publicWorldTitle(value) {
  const aliases = {
    'Adventure Classic': 'приключенческая история',
    'Romantic Story': 'романтическая история',
    'Fantasy Epic': 'фэнтези',
    'Cyberpunk Dream': 'русский киберпанк',
    'Hogwarts World': 'магическая школа',
    adventure_classic: 'приключенческая история',
    romantic_story: 'романтическая история',
    fantasy_epic: 'фэнтези',
    cyberpunk_dream: 'русский киберпанк',
    hogwarts_world: 'магическая школа',
    disney_light: 'романтическая история',
  };
  return aliases[value] || value || '';
}
// ANTAGONIST_ROLE_V1: the constructor uses the existing persisted relation field.
const antagonistHero = activeHeroes.find(hero => Number(hero.n) === 2 && hero.relation === 'Антагонист главного героя');
const antagonistPolicy = antagonistHero
  ? 'РОЛЬ ГЕРОЯ 2 — АНТАГОНИСТ: ' + antagonistHero.name + ' противостоит главному герою 1. Это обязательная роль, приоритетнее общих жанровых рекомендаций о паре, команде, совместном пути или романтическом сближении. Сохраняй имя, описание, возраст, факты и внешность героя 2. Дай ему собственную понятную цель и мотив; его действия создают препятствия и меняют решения героя 1. Не превращай его в напарника, постоянного помощника или романтического партнера по умолчанию. Конфликт развивается через поступки и последствия в плане и главах; не своди роль к слову злодей или декоративной ссоре. Согласуй развязку с развитием конфликта; примирение не обязательно и не отменяет противодействие задним числом. Для детской истории противодействие остается эмоционально безопасным: без жестокости, травмирующих угроз и предательства близких. Не делай внешность человека зловещей из-за сюжетной роли. При иллюстрациях выбирай героев по фактической сцене, а не обязательно вместе.'
  : '';

const protagonistPolicy = antagonistHero ? antagonistPolicy : protagonistPolicyFor(protagonistMode);
const heroes = activeHeroes
  .filter((hero) => hero.name || hero.description || hero.relation)
  .map((hero) => 'Герой ' + hero.n + ': ' + (hero.name || 'без имени') + ' - ' + (hero.description || 'описание не задано') + ' - ' + (hero.relation || 'роль не задана'))
  .join('\n');
const style = order.illustrationStyle || 'storybook';
const worldBrief = [
  (bible.worldTitle || order.world) ? 'Жанровый режим: ' + publicWorldTitle(bible.worldTitle || order.world) : '',
  bible.worldEnv ? 'Среда и законы: ' + bible.worldEnv : '',
  bible.worldRel ? 'Отношения: ' + bible.worldRel : '',
  bible.worldMotifs ? 'Мотивы: ' + bible.worldMotifs : '',
  bible.worldDramaturgy ? 'Драматургия: ' + bible.worldDramaturgy : '',
  bible.worldConflict ? 'Конфликт: ' + bible.worldConflict : '',
  bible.worldVisual ? 'Визуальный язык: ' + bible.worldVisual : '',
].filter(Boolean).join('\n');
const firstChapterText = firstChapter.text || (Array.isArray(firstChapter.textBlocks) ? firstChapter.textBlocks.join('\n\n') : text.preview?.text || '');
const planText = laterPlan.map((chapter) => 'Глава ' + chapter.n + ': ' + chapter.title + '. Бит: ' + chapter.beat + '. Зафиксированное визуальное ТЗ: ' + chapter.visualBrief + '. Видимые герои: ' + (chapter.heroNumbers || []).join(', ') + '. Ракурс: ' + chapter.shotType + '. Физическое расположение: ' + (chapter.physicalPlacement || '') + '. Пространственные отношения: ' + (chapter.spatialRelations || []).join('; ') + '. Запрещенные искажения сцены: ' + (chapter.forbiddenMisreads || []).join('; ')).join('\n');
const requestedShape = laterPlan.map((chapter) => {
  const blockSlots = Array.from({ length: chapter.textBlockTarget }, () => '"..."').join(', ');
  return '{ "n": ' + chapter.n + ', "title": "...", "summary": "...", "textBlocks": [' + blockSlots + '] }';
}).join(', ');
const chapterCharacterTargets = { 2: '3400-3700', 3: '4900-5200', 4: '4900-5200', 5: '4000-4300' };
const blockPlanText = laterPlan.map((chapter) => 'Глава ' + chapter.n + ': ровно ' + chapter.textBlockTarget + ' текстовых блоков, общий объем ' + (chapterCharacterTargets[chapter.n] || (chapter.textBlockTarget * 850) + '-' + (chapter.textBlockTarget * 950)) + ' знаков').join('; ');
// STORY_DRAMATURGY_V1 — retained by durable chapter-scoped requests.
const continuationDramaturgy = "РАЗВИТИЕ УТВЕРЖДЕННОГО ВНУТРЕННЕГО ПЛАНА: сохраняй цель, ставки и причинные связи из story bible и chapterPlan. Вторая глава непосредственно развивает открытый вопрос финала первой главы и дает существенное продвижение к ответу. Далее последствия действий расширяют масштаб и повышают цену решения; не обнуляй уже достигнутое и не заменяй сквозной конфликт новым маленьким поручением.\nВ каждой главе покажи конкретное действие, препятствие, выбор и результат, который меняет дальнейшее положение героя. Предпоследняя глава подводит к трудному решению; финальная разрешает основной конфликт поступком героя и показывает ощутимые последствия. Не решай все случайной находкой, внезапной магией, чужой помощью или одним разговором. Не переписывай уже зафиксированные события и визуальные сцены ради увеличения масштаба; при продолжении старых книг уважай их исходный план и обещания первой главы.";
const optionalArtifactPolicy = effectiveArtifactCanon
  ? "ВАЖНАЯ ДЕТАЛЬ ЗАДАНА: сохраняй указанный канон предмета и уже написанные события, не подменяй предмет."
  : "ВАЖНАЯ ДЕТАЛЬ НЕ ЗАДАНА: не вводи новый компас или другой сюжетный артефакт как центральную цель, источник силы, универсальное решение или повторяющийся символ. Обычные предметы обстановки допустимы. Сохраняй уже написанные события первой главы и существующий план старой книги; не добавляй новый обязательный предмет для развития или разрешения конфликта.";
const systemText = (antagonistPolicy ? antagonistPolicy + "\n\n" : "") + continuationDramaturgy + "\n\n" + optionalArtifactPolicy + '\n\n' + 'Ты - автор персональных книг Fairyteller. Пиши на русском языке, без буквы е с точками. Продолжай уже начатую историю строго по именам, отношениям, миру, возрасту и фактам пользователя. Не добавляй известных copyrighted персонажей и не копируй чужие вселенные. Не упоминай служебные названия жанров, workflow, world key или внутренние labels: Adventure Classic, Romantic Story, Fantasy Epic, Cyberpunk Dream, Hogwarts World, adventure_classic, romantic_story, fantasy_epic, cyberpunk_dream, hogwarts_world, disney_light. Если это романтическая история, держи romcom-логику: каждую главу меняй степень доверия между героями через действие, смешное осложнение, заботу, почти-признание, недопонимание без жестокости и честный выбор. Если это фэнтези, сохраняй эпический сюжет, но пиши проще: меньше метафор и абстрактных символов, больше действий, предметов, правил магии, последствий выбора и коротких живых реплик. Если это русский киберпанк, снижай градус: меньше эпитетов, неона и метафор, больше конкретных городских деталей, технической проблемы, наблюдения, действия и коротких реплик. Верни только валидный JSON, без markdown. Внутри textBlocks запрещены символы «, », двойные кавычки и любые цитаты в кавычках; не используй списки и переносы строк. Проза должна быть предметной и редакторски чистой: меньше декоративных эпитетов, меньше атмосферных списков и сенсорных клише вроде: воздух был наполнен запахами выпечки и свежескошенной травы. Оставляй только детали, которые работают на действие, характер, место или сюжетную задачу; в одном абзаце достаточно 1-2 точных образов. Диалоги должны занимать не больше 30% текста главы и каждого textBlocks[i]; остальное - действие, наблюдение, выбор героя и последствия. Прямую речь оформляй только русским тире, без внешних кавычек. Каждый диалоговый абзац должен однозначно называть говорящего и заканчиваться короткой авторской подписью. Допустимые формы: — Реплика, — сказал герой. — Реплика? — спросила героиня. Для нескольких фраз одного героя ставь все его слова до единственной финальной подписи: — Первая фраза. Вторая фраза, — добавил герой. Запрещена разорванная конструкция вида: — Реплика, — сказал герой. — Продолжение реплики. Не оставляй самостоятельные реплики без подписи говорящего. Не используй кавычки для диалога, мыслей, воспоминаний, названий дел, сообщений и подписей на предметах. Если герой вспоминает чужие слова или думает о сказанной фразе, перескажи это косвенной речью без цитаты. Не выдавай косвенную речь за цитату и не оформляй обычное действие как реплику. Если после реплики идет действие без глагола речи, закрывай реплику точкой и пиши действие отдельным повествовательным предложением без начального тире. Не оставляй отдельные строки вида: — Он улыбнулся / — Она посмотрела.';
const userText = 'Нужно дописать персональную книгу после первой главы. Первая глава уже готова; сейчас напиши главы 2-' + chaptersTarget + ', чтобы получилась цельная книга для печатного PDF.\n\n' +
  'Название книги: ' + (bible.bookTitle || text.preview?.title || '') + '\n' +
  'Подзаголовок: ' + (bible.subtitle || '') + '\n' +
  'Аннотация книги: ' + (bible.readerBlurb || bible.coverSummary || text.preview?.summary || '') + '\n' +
  'Мир:\n' + (worldBrief || order.world || '') + '\n\n' +
  'Место действия: ' + (order.location || bible.location || '') + '\n' +
  (effectiveArtifactCanon ? 'Канон важного предмета: ' + effectiveArtifactCanon + '\n' : '') +
  'Стиль иллюстраций для визуальной логики: ' + style + '\n' +
  'Режим героев: ' + protagonistMode + '. ' + protagonistPolicy + '\n' +
  'Возрастная тональность: ' + childTonePolicy + '\n\n' +
  'Персонажи:\n' + (heroes || 'Персонажи не заданы; продолжай по первой главе без добавления постоянной команды.') + '\n\n' +
  'Первая глава, которую нельзя переписывать:\n' + firstChapterText + '\n\n' +
  'План следующих глав:\n' + planText + '\n\n' +
  'Требования к главам 2-' + chaptersTarget + ': соблюдай точное число текстовых блоков и общий объем по главам: ' + blockPlanText + '. Каждый textBlocks[i] является одной печатной страницей: 850-950 знаков, цель около 900 знаков. Каждый блок состоит из 3-5 абзацев разной длины; чередуй действие, наблюдение, реакцию и при необходимости короткий диалог, не собирай страницу в один сплошной абзац и не дроби каждое предложение отдельно. Разделяй абзацы внутри JSON-строки экранированной последовательностью \\n\\n. Перед ответом проверь длину каждого блока и общий объем каждой главы; расширяй короткий блок без нового сюжетного поворота. Диалоги должны занимать не больше 30% текста каждой главы и каждого textBlocks[i]. Прямая речь только через русское тире. Каждый диалоговый абзац заканчивай короткой подписью говорящего. Все фразы одного героя ставь до этой подписи: — Первая фраза. Вторая фраза, — добавил герой. Не пиши продолжение реплики после авторской подписи и не оставляй самостоятельную реплику без указания говорящего. Нельзя выдавать косвенную речь за цитату, нельзя оформлять обычное действие как реплику. Мысли, воспоминания, названия дел, сообщения и подписи на предметах передавай без кавычек; если нужно вспомнить сказанную фразу, перескажи ее косвенной речью. Меньше декоративных эпитетов, атмосферных перечислений и сенсорных клише вроде: воздух был наполнен запахами...: оставляй только детали, которые двигают сцену, характер, место или сюжетную задачу. Без markdown, без нумерованных списков, без заголовков внутри textBlocks. Не пересказывай первую главу; продолжай сюжет. Для романтической истории каждая следующая глава должна двигать отношения: совместная цель, смешное осложнение, почти-признание, недопонимание без жестокости, выбор уязвимости и финальный теплый жест. Для фэнтези каждая следующая глава должна двигать сюжет через ясную задачу, препятствие, новое правило магии или цену решения, и конкретный выбор героя; не разгоняй текст метафорами и общими словами о судьбе, свете, тьме и сердце. Для русского киберпанка каждая следующая глава должна двигать сюжет через конкретную городскую задачу, техническое препятствие, проверку доверия и ясный риск; не перегружай текст эпитетами, неоном, холодом, тенями и абстрактными рассуждениями о системе. Финальная глава должна закрыть арку и дать теплое послевкусие. Если режим героев SOLO, каждая глава должна оставлять одного главного героя центром действия; не вводи постоянного спутника, пару или команду. Аннотация/coverSummary должна быть читательским описанием книги, не описанием обложки или картинки: 140-260 знаков, максимум два коротких предложения.\n\n' +
