function extractJsonCandidate(text) {
  let candidate = stripJsonMarkdownFences(text);
  const firstBrace = candidate.indexOf('{');
  const lastBrace = candidate.lastIndexOf('}');
  if (firstBrace >= 0 && lastBrace > firstBrace) candidate = candidate.slice(firstBrace, lastBrace + 1);
  return candidate;
}

function escapeControlCharsInsideStrings(text) {
  let result = '';
  let inString = false;
  let escaped = false;
  for (const char of text) {
    if (escaped) {
      result += char;
      escaped = false;
      continue;
    }
    if (char === '\\') {
      result += char;
      escaped = true;
      continue;
    }
    if (char === '"') {
      inString = !inString;
      result += char;
      continue;
    }
    if (inString && char === '\n') {
      result += '\\n';
      continue;
    }
    if (inString && char === '\r') {
      result += '\\r';
      continue;
    }
    if (inString && char === '\t') {
      result += '\\t';
      continue;
    }
    result += char;
  }
  return result;
}

function repairLikelyJson(text) {
  return String(text || '')
    .replace(/,\s*([}\]])/g, '$1')
    .replace(/"\s*\n\s*"/g, '"\n,"')
    .replace(/}\s*\n\s*"/g, '}\n,"')
    .replace(/]\s*\n\s*"/g, ']\n,"');
}

