    RETRY_DETAIL_INSTRUCTION,
    showHeroes ? 'Mood: wonder, discovery, mystery, warm magic, cinematic light. Keep the main hero calm, friendly and age-appropriate. Avoid violence, injury, weapons, horror, gore, scary faces or aggressive action.' : 'Mood: wonder, discovery, mystery, warm light. Environment and objects only.',
  ].join('\n');
}

