function imageDimensionsFromInlineData(inlineData) {
  const buffer = Buffer.from(inlineData?.data || '', 'base64');
  if (buffer.length >= 24 && buffer.toString('ascii', 1, 4) === 'PNG') {
    return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
  }
  if (buffer.length > 4 && buffer[0] === 0xff && buffer[1] === 0xd8) {
    let offset = 2;
    while (offset + 9 < buffer.length) {
      if (buffer[offset] !== 0xff) { offset += 1; continue; }
      const marker = buffer[offset + 1];
      const length = buffer.readUInt16BE(offset + 2);
      if ([0xc0, 0xc1, 0xc2, 0xc3, 0xc5, 0xc6, 0xc7, 0xc9, 0xca, 0xcb, 0xcd, 0xce, 0xcf].includes(marker)) {
        return { height: buffer.readUInt16BE(offset + 5), width: buffer.readUInt16BE(offset + 7) };
      }
      offset += 2 + Math.max(length, 2);
    }
  }
  return null;
}

function coverAspectIssue(part) {
  const dimensions = imageDimensionsFromInlineData(part?.inlineData);
  if (!dimensions?.width || !dimensions?.height) return null;
  const ratio = dimensions.width / dimensions.height;
  if (ratio < 1.3 || ratio > 1.85) {
    return 'Generated cover image aspect ratio ' + ratio.toFixed(3) + ' from ' + dimensions.width + 'x' + dimensions.height + '; expected landscape 3:2 for the front-cover frame';
  }
  return null;
}

function enforceCoverAspect(part, reason) {
  const issue = coverAspectIssue(part);
  if (!issue) return { part, reason };
  return { part: null, reason: [issue, reason].filter(Boolean).join(' / ') };
}

